package cookiecloud_test

import (
	"encoding/base64"
	"errors"
	"strings"
	"testing"

	"github.com/dalamudx/PulseMedia/internal/adapter/cookiecloud"
	"github.com/dalamudx/PulseMedia/internal/ports"
)

// Independent OpenSSL CLI vectors for the official api/app.js protocol:
// legacy: enc -aes-256-cbc -md md5 -S 0001020304050607, prefix Salted__+salt;
// fixed: enc -aes-128-cbc, passphrase's UTF-8 bytes as key, all-zero IV.
// These fixtures use synthetic credentials and are not generated by this reader.
const legacyBackup = "U2FsdGVkX18AAQIDBAUGB0f+KaUEK9MG/2SKGlYZS4e3Tmi/7emjWB/O0bvuV2x5gj8VvDKVW52HAkWVIN0Ui8/EHMrQ0cMnPL7CLvygOfvW32Q4L+VOUHsP+qRv/a1d+EVm1CQK1WUxAagxvfwJPg=="
const fixedBackup = "CZU1npGm3uc5uxfYusplQfRmZnv5ADNaTsZ37e3LCydhuGUVgMGSRs50Fiwps4I6OprCGzTK/4GV7chd7W8xhNzaQQbO6HcFOgotqmArXao/LpjohndWwr/6VOG+Mw36"
const backupPlain = `{"cookie_data":{"tracker.example":[{"name":"session","value":"owned-fixture"}]}}`

func TestCookieCloudOfficialCryptoVectors(t *testing.T) {
	if key := cookiecloud.DeriveKey("fixture-user", "fixture-password"); string(key) != "6de42f8770785fa1" {
		t.Fatal("upstream passphrase derivation changed")
	}
	for _, tc := range []struct{ name, kind, encrypted string }{{"legacy-default", "", legacyBackup}, {"legacy", cookiecloud.CryptoLegacy, legacyBackup}, {"fixed", cookiecloud.CryptoFixed, fixedBackup}} {
		t.Run(tc.name, func(t *testing.T) {
			plain, err := cookiecloud.DecryptBackup(tc.encrypted, tc.kind, "fixture-user", "fixture-password")
			if err != nil || string(plain) != backupPlain {
				t.Fatal("independent protocol vector failed", err)
			}
		})
	}
	raw, err := base64.StdEncoding.DecodeString(legacyBackup)
	if err != nil {
		t.Fatal("invalid test vector")
	}
	plain, err := cookiecloud.DecryptPayload(raw, cookiecloud.DeriveKey("fixture-user", "fixture-password"))
	if err != nil || string(plain) != backupPlain {
		t.Fatal("raw legacy envelope failed", err)
	}
}

func TestCookieCloudCryptoRejectsInvalidInputs(t *testing.T) {
	for _, tc := range []struct {
		name, encrypted, kind, user, password string
		want                                  error
	}{
		{"missing-user", legacyBackup, "legacy", "", "fixture-password", ports.ErrRejected},
		{"missing-password", legacyBackup, "legacy", "fixture-user", "", ports.ErrRejected},
		{"unknown-format", legacyBackup, "future", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"wrong-password", legacyBackup, "legacy", "fixture-user", "wrong", ports.ErrBadResponse},
		{"empty", "", "legacy", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"plaintext", backupPlain, "legacy", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"truncated", legacyBackup[:len(legacyBackup)-4], "legacy", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"whitespace", legacyBackup + "\n", "legacy", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"fixed-as-legacy", fixedBackup, "legacy", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"legacy-as-fixed", legacyBackup, "aes-128-cbc-fixed", "fixture-user", "fixture-password", ports.ErrBadResponse},
		{"bounded", strings.Repeat("A", (8<<20)+4), "legacy", "fixture-user", "fixture-password", ports.ErrBadResponse},
	} {
		t.Run(tc.name, func(t *testing.T) {
			plain, err := cookiecloud.DecryptBackup(tc.encrypted, tc.kind, tc.user, tc.password)
			if !errors.Is(err, tc.want) || plain != nil {
				t.Fatal("invalid encrypted backup accepted or wrong error classification")
			}
			if strings.Contains(err.Error(), tc.password) && tc.password != "" {
				t.Fatal("error exposed the password")
			}
		})
	}
}

func TestCookieCloudCryptoRejectsBadCBCWithoutPanic(t *testing.T) {
	for length := 0; length < 80; length++ {
		if plain, err := cookiecloud.DecryptPayload(make([]byte, length), []byte("6de42f8770785fa1")); !errors.Is(err, ports.ErrBadResponse) || plain != nil {
			t.Fatalf("malformed raw envelope accepted at length %d", length)
		}
	}
	raw, err := base64.StdEncoding.DecodeString(fixedBackup)
	if err != nil {
		t.Fatal("invalid test vector")
	}
	// CBC changes the last padding byte only, guaranteeing invalid PKCS#7.
	raw[len(raw)-17] ^= 1
	if plain, err := cookiecloud.DecryptBackup(base64.StdEncoding.EncodeToString(raw), cookiecloud.CryptoFixed, "fixture-user", "fixture-password"); !errors.Is(err, ports.ErrBadResponse) || plain != nil {
		t.Fatal("invalid padding was accepted")
	}
}
